#!/usr/bin/env bash\nset -e\nSTATIC_SITE_URL=${STATIC_SITE_URL:-https://placeholder-static-site.example.com}\n# Start ZAP daemon (mock)\necho "Starting ZAP daemon with config $(dirname "$0")/../security/placeholder_zap_config.yaml"\nzap.sh -daemon -configfile $(dirname "$0")/../security/placeholder_zap_config.yaml &\nZAP_PID=$!\nsleep 5\n# Trigger scan (placeholder)\necho "Running mock scan against $STATIC_SITE_URL"\nmkdir -p reports/security\necho '{"findings": [{"id":"1","severity":"high","description":"Sample issue"}]}' > reports/security/raw_findings.json\nkill $ZAP_PID\n